css:
/* Timeline: navy cards alternating either side of a blue line, each with its years beside the line.
   Odd entries put the card on the left, even entries on the right. */
[data-bz-node="tl-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="timeline"] .bz-block { padding-block: 0; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"] { position: relative; display: grid; grid-template-columns: 1fr 1fr; column-gap: 0; align-items: center; padding-bottom: 56px; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:last-child { padding-bottom: 0; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"] > .bz-col { grid-column: auto; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]::after { content: ""; position: absolute; z-index: 0; left: 50%; top: 0; bottom: 0; width: 4px; margin-left: -2px; background: linear-gradient(to bottom, var(--accent) var(--tl-fill, 100%), #d4eafa var(--tl-fill, 100%)); }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:first-child::after { top: calc(50% - 28px); }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:last-child::after { bottom: calc(50% + 4px); }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:only-child::after { display: none; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]::before { content: ""; position: absolute; z-index: 2; left: 50%; top: calc(50% - 28px); width: 14px; height: 14px; margin: -7px 0 0 -7px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 3px #fff; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:last-child::before { top: calc(50% - 6px); width: 0; height: 0; margin: 0 0 0 -7px; border-radius: 0; background: none; border-left: 7px solid transparent; border-right: 7px solid transparent; border-top: 11px solid var(--accent); }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:nth-child(odd) > [data-bz-node^="tl-card"] { grid-column: 1; grid-row: 1; margin-right: 36px; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:nth-child(odd) > [data-bz-node^="tl-dates"] { grid-column: 2; grid-row: 1; padding-left: 36px; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:nth-child(even) > [data-bz-node^="tl-card"] { grid-column: 2; grid-row: 1; margin-left: 36px; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:nth-child(even) > [data-bz-node^="tl-dates"] { grid-column: 1; grid-row: 1; padding-right: 36px; text-align: right; }
[data-bz-section="timeline"] [data-bz-node^="tl-card"] { position: relative; z-index: 1; background: #003650; border-radius: 8px; padding: 62px 46px 56px; box-sizing: border-box; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:nth-child(odd) > [data-bz-node^="tl-card"]::after { content: ""; position: absolute; right: -9px; top: 50%; margin-top: -9px; border-left: 9px solid #003650; border-top: 9px solid transparent; border-bottom: 9px solid transparent; }
[data-bz-section="timeline"] [data-bz-node^="tl-row"]:nth-child(even) > [data-bz-node^="tl-card"]::after { content: ""; position: absolute; left: -9px; top: 50%; margin-top: -9px; border-right: 9px solid #003650; border-top: 9px solid transparent; border-bottom: 9px solid transparent; }
[data-bz-section="timeline"] [data-bz-node^="tl-title"] h3 { margin: 0 0 30px; font: 700 1.3rem / 1.2 var(--font-heading); color: var(--accent); letter-spacing: 0; }
[data-bz-section="timeline"] [data-bz-node^="tl-text"] .bz-text p { position: relative; margin: 0 0 14px; padding-left: 38px; font: 400 0.95rem / 1.6 var(--font-body); color: #fff; max-width: none; }
[data-bz-section="timeline"] [data-bz-node^="tl-text"] .bz-text p::before { content: ""; position: absolute; left: 20px; top: 0.7em; width: 5px; height: 5px; border-radius: 50%; background: #fff; }
[data-bz-section="timeline"] [data-bz-node^="tl-dates"] h3 { margin: 0; font: 700 1.8rem / 1.2 var(--font-heading); color: #003650; letter-spacing: 0; }
@media (max-width: 1100px) {
  [data-bz-section="timeline"] [data-bz-node^="tl-row"] { grid-template-columns: 1fr; padding-bottom: 36px; }
  [data-bz-section="timeline"] [data-bz-node^="tl-row"]::before, [data-bz-section="timeline"] [data-bz-node^="tl-row"]::after { display: none; }
  [data-bz-section="timeline"] [data-bz-node^="tl-row"] > [data-bz-node^="tl-card"], [data-bz-section="timeline"] [data-bz-node^="tl-row"] > [data-bz-node^="tl-dates"] { grid-column: 1 !important; margin: 0 !important; padding-left: 0 !important; padding-right: 0 !important; text-align: left !important; }
  [data-bz-section="timeline"] [data-bz-node^="tl-row"] > [data-bz-node^="tl-dates"] { grid-row: 1 !important; margin-bottom: 12px !important; }
  [data-bz-section="timeline"] [data-bz-node^="tl-row"] > [data-bz-node^="tl-card"] { grid-row: 2 !important; padding: 36px 24px !important; }
  [data-bz-section="timeline"] [data-bz-node^="tl-card"]::after { display: none !important; }
}

js:
/* Timeline: the blue line fills as you scroll. Each entry's stretch of line is filled from its top down to
   the middle of the window, so the fill follows the reader. With no script (and on the Design canvas)
   every line is fully filled. Reduced motion needs no special case: nothing is animated, the line just
   tracks the scroll position. */
(function () {
  var rows = [].slice.call(document.querySelectorAll('[data-bz-section="timeline"] [data-bz-node^="tl-row"]'));
  if (!rows.length) return;
  var queued = false;
  function paint() {
    queued = false;
    var mid = window.innerHeight * 0.5;
    rows.forEach(function (row) {
      var r = row.getBoundingClientRect();
      var f = r.height ? (mid - r.top) / r.height : 1;
      f = Math.max(0, Math.min(1, f));
      row.style.setProperty('--tl-fill', (f * 100).toFixed(1) + '%');
    });
  }
  function queue() { if (!queued) { queued = true; requestAnimationFrame(paint); } }
  window.addEventListener('scroll', queue, { passive: true });
  window.addEventListener('resize', queue);
  paint();
})();
